### file: wp-content/mu-plugins/shipgate-errors.php
<?php
/**
 * Plugin Name: Shipgate error handling
 */
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

// noindex on 404/410 pages (RTE-004 / IDX-006): wp_robots_no_robots() adds the noindex directive.
add_filter( 'wp_robots', function ( $robots ) {
	return is_404() ? wp_robots_no_robots( $robots ) : $robots;
} );

add_action( 'template_redirect', function () {
	global $wp_query, $wpdb;

	// A 404 while the database is failing is an outage, not a missing page: answer 503 (RTE-007).
	if ( is_404() ) {
		$wpdb->suppress_errors( true );
		if ( '1' !== (string) $wpdb->get_var( 'SELECT 1' ) ) { // ask again: $wpdb->last_error is cleared by the next successful query
			require WP_CONTENT_DIR . '/db-error.php'; // sends 503 + Retry-After and exits
			exit;
		}
	}

	// 410 for retired paths that have no successor (RTE-004). Core then loads 404.php.
	$path    = (string) wp_parse_url( isset( $_SERVER['REQUEST_URI'] ) ? wp_unslash( $_SERVER['REQUEST_URI'] ) : '', PHP_URL_PATH );
	$retired = array( '/old-page/', '/discontinued-product/' );
	if ( in_array( trailingslashit( $path ), $retired, true ) ) {
		$GLOBALS['shipgate_gone'] = true;
		$wp_query->set_404();
		status_header( 410 );
		return;
	}

	// Unknown value for a custom rewrite/query var (e.g. /item/<slug>/): decide the 404 before any output.
	$slug = get_query_var( 'sg_item' );
	if ( $slug && ! get_posts( array( 'post_type' => 'item', 'name' => $slug, 'posts_per_page' => 1, 'fields' => 'ids' ) ) ) {
		$wp_query->set_404();
		status_header( 404 );
		nocache_headers();
	}
} );
