<?php
/**
 * Plugin Name: Shipgate contact form handler
 */
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

add_action( 'admin_post_nopriv_shipgate_contact', 'shipgate_handle_contact' ); // visitors
add_action( 'admin_post_shipgate_contact', 'shipgate_handle_contact' );        // logged-in users

function shipgate_contact_done() {
	wp_safe_redirect( add_query_arg( 'sent', '1', home_url( '/contact/' ) ), 303 ); // POST -> 303 -> GET
	exit; // wp_safe_redirect() does not exit
}

function shipgate_handle_contact() {
	// SEC-024: CSRF.
	$nonce = isset( $_POST['sg_nonce'] ) ? sanitize_text_field( wp_unslash( $_POST['sg_nonce'] ) ) : '';
	if ( ! wp_verify_nonce( $nonce, 'shipgate_contact' ) ) {
		wp_die( 'This form expired. Go back, reload the page and send it again.', 'Form expired', array( 'response' => 403, 'back_link' => true ) );
	}

	// SEC-054: 5 submissions per 10 minutes per client (not atomic; good enough for a contact form).
	$ip   = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : 'unknown';
	$key  = 'sg_contact_' . wp_hash( $ip );
	$hits = (int) get_transient( $key );
	if ( $hits >= 5 ) {
		header( 'Retry-After: 600' );
		wp_die( 'Too many messages. Please try again later.', 'Too many requests', array( 'response' => 429 ) );
	}
	set_transient( $key, $hits + 1, 10 * MINUTE_IN_SECONDS );

	// SEC-055: honeypot. Same success-looking response, no side effect. (Alternative: Cloudflare Turnstile, cf-turnstile-response, verified server-side.)
	if ( ! empty( $_POST['company_url'] ) ) {
		shipgate_contact_done();
	}

	// Sanitize and length-limit server-side.
	$name    = isset( $_POST['name'] ) ? sanitize_text_field( wp_unslash( $_POST['name'] ) ) : '';
	$email   = isset( $_POST['email'] ) ? sanitize_email( wp_unslash( $_POST['email'] ) ) : '';
	$message = isset( $_POST['message'] ) ? sanitize_textarea_field( wp_unslash( $_POST['message'] ) ) : '';
	if ( '' === $name || ! is_email( $email ) || mb_strlen( $message ) < 10 || mb_strlen( $name ) > 100 || mb_strlen( $message ) > 5000 ) {
		wp_die( 'Please check your name, email and message and try again.', 'Invalid form', array( 'response' => 400, 'back_link' => true ) );
	}

	// >>> the one line the project replaces: the real destination (mail, or a webhook with wp_remote_post( FORM_WEBHOOK_URL,
	// array( 'timeout' => 8, 'headers' => array( 'Content-Type' => 'application/json' ), 'body' => wp_json_encode( ... ) ) )
	// where is_wp_error() or a response code outside 2xx counts as failure) <<<
	$sent = wp_mail( get_option( 'admin_email' ), 'New contact message', "From: $name <$email>\n\n$message", array( 'Reply-To: ' . $email ) );

	if ( ! $sent ) { // RES-008: never a success page after a failed delivery
		wp_die( 'We could not send your message. Please try again later.', 'Message not sent', array( 'response' => 502, 'back_link' => true ) );
	}

	shipgate_contact_done();
}

WordPress 5.7+ (core filters since 5.7; docs checked through 7.0). WordPress has no CSP nonce API, but core builds every enqueued <script src> with wp_get_script_tag() (filter wp_script_attributes) and every inline/localized/translation script with wp_get_inline_script_tag() (filter wp_inline_script_attributes), so one per-request nonce can be stamped on all core-printed scripts. NOT covered, and blocked by this CSP: scripts a plugin or theme prints as raw <script> text or inline on* handlers; fix or remove those. Core has no nonce hook for inline <style>, so style-src keeps 'unsafe-inline' (scripts stay strict). The header is built per request: bypass the page cache for HTML, or a cached page serves a stale nonce and every script is blocked. wp_headers covers front-end pages only (not wp-admin, wp-login.php, REST, or static files).
### file: wp-content/mu-plugins/shipgate-headers.php
<?php
/**
 * Plugin Name: Shipgate security headers
 */
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

function shipgate_csp_nonce() {
	static $nonce = null;
	if ( null === $nonce ) {
		$nonce = base64_encode( random_bytes( 16 ) ); // fresh per request
	}
	return $nonce;
}

// Every script tag core prints (enqueued src tags, inline, localized data, translations).
add_filter( 'wp_script_attributes', function ( $attributes ) {
	$attributes['nonce'] = shipgate_csp_nonce();
	return $attributes;
} );
add_filter( 'wp_inline_script_attributes', function ( $attributes, $data ) {
	$attributes['nonce'] = shipgate_csp_nonce();
	return $attributes;
}, 10, 2 );

add_filter( 'wp_headers', function ( $headers ) {
	$nonce = shipgate_csp_nonce();
	// SEC-010 / SEC-075. With the consent loader add its connect-src / img-src hosts; never add Google hosts to script-src.
	$headers['Content-Security-Policy'] = "default-src 'self'; script-src 'self' 'nonce-{$nonce}' 'strict-dynamic'; "
		. "style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self'; "
		. "object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'; upgrade-insecure-requests";
	$headers['X-Content-Type-Options'] = 'nosniff';
	$headers['Referrer-Policy']        = 'strict-origin-when-cross-origin';
	$headers['Permissions-Policy']     = 'camera=(), microphone=(), geolocation=()';
	if ( is_ssl() ) {
		$headers['Strict-Transport-Security'] = 'max-age=63072000; includeSubDomains';
	}
	// PRF-008: logged-in users already get nocache headers from core; anonymous HTML revalidates.
	if ( ! isset( $headers['Cache-Control'] ) ) {
		$headers['Cache-Control'] = 'public, max-age=0, must-revalidate';
	}
	return $headers;
} );
