WordPress 5.5+ (permission_callback is required for REST routes). The URL is /wp-json/site/v1/health (or /?rest_route=/site/v1/health without pretty permalinks); point verifyEnv.health at it. If MySQL is unreachable at load, WordPress serves wp-content/db-error.php (503, see the error-pages recipe) before REST starts, which is also a non-200 with no version text. The route is public on purpose and reveals nothing but ok/unavailable. Add other critical dependencies next to the SELECT 1 check.
### file: wp-content/mu-plugins/shipgate-health.php
<?php
/**
 * Plugin Name: Shipgate health endpoint
 */
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

add_action( 'rest_api_init', function () {
	register_rest_route( 'site/v1', '/health', array(
		'methods'             => 'GET',
		'callback'            => 'shipgate_health',
		'permission_callback' => '__return_true', // public on purpose (OPS-002)
	) );
} );

function shipgate_health() {
	global $wpdb;

	$wpdb->suppress_errors( true ); // a failed query must not print SQL or error text
	$ok = ( '1' === $wpdb->get_var( 'SELECT 1' ) ); // get_var() returns null on failure

	// Body: status only. No versions, hostnames, table prefix or error text.
	$response = new WP_REST_Response( array( 'status' => $ok ? 'ok' : 'unavailable' ), $ok ? 200 : 503 );
	$response->header( 'Cache-Control', 'no-store' );
	return $response;
}

WordPress 5.5+ (core sitemaps at /wp-sitemap.xml). Mode comes from DEPLOY_ENV only: "production" is the one production value and anything else, including unset, is non-production. Do not use wp_get_environment_type()/WP_ENVIRONMENT_TYPE for this: it defaults to "production" when unset. getenv() sees the variable only if the PHP runtime passes it through (php-fpm clear_env = no or an env[] line; Apache SetEnv may not reach getenv, so test it). SITE_URL must equal the WordPress Site Address (Settings > General): the Sitemap line uses SITE_URL while core builds the sitemap URLs from the Site Address. Delete any physical robots.txt in the web root: it shadows the WordPress-generated one. Since 5.3 core no longer prints "Disallow: /" for a hidden site, so the robots_txt filter below writes the whole file. Core sitemaps list posts, taxonomies and users: open /wp-sitemap.xml and drop any provider whose URLs are noindex. X-Robots-Tag covers every request PHP handles; static files (theme assets, uploads) do not reach PHP, so send it from the web server on non-production hosts.
### file: wp-config.php (above the "That's all, stop editing" line)
define( 'DEPLOY_ENV', getenv( 'DEPLOY_ENV' ) ?: 'development' );
define( 'SHIPGATE_SITE_URL', rtrim( getenv( 'SITE_URL' ) ?: 'https://example.com', '/' ) );
### file: wp-content/mu-plugins/shipgate-indexing.php
<?php
/**
 * Plugin Name: Shipgate indexing control
 */
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

$shipgate_is_production = ( defined( 'DEPLOY_ENV' ) && 'production' === DEPLOY_ENV );

// "Discourage search engines" follows the environment, so a staging database import cannot hide production.
add_filter( 'pre_option_blog_public', function () use ( $shipgate_is_production ) {
	return $shipgate_is_production ? '1' : '0';
} );

if ( ! $shipgate_is_production ) {
	add_filter( 'wp_robots', 'wp_robots_no_robots' );            // <meta name="robots" content="noindex">
	add_filter( 'wp_sitemaps_enabled', '__return_false' );        // /wp-sitemap.xml answers 404
	// IDX-005: every non-production response. A mu-plugin loads on every PHP-handled request (pages, REST, login, admin-post, robots.txt, sitemaps).
	if ( ! headers_sent() ) {
		header( 'X-Robots-Tag: noindex, nofollow' );
	}
	add_filter( 'rest_post_dispatch', function ( $result ) { // the REST server sends its own "noindex"; replace it
		$result->header( 'X-Robots-Tag', 'noindex, nofollow' );
		return $result;
	} );
} else {
	// Only the indexable public content types in the sitemap.
	add_filter( 'wp_sitemaps_post_types', function ( $post_types ) {
		return array_intersect_key( $post_types, array_flip( array( 'page', 'post' ) ) );
	} );
}

add_filter( 'robots_txt', function ( $output, $public ) use ( $shipgate_is_production ) {
	if ( ! $shipgate_is_production ) {
		return "User-agent: *\nDisallow: /\n"; // no Sitemap line
	}
	// Never disallow wp-content / wp-includes (CSS, JS, images).
	return "User-agent: *\nAllow: /\nDisallow: /wp-admin/\nAllow: /wp-admin/admin-ajax.php\n\nSitemap: " . SHIPGATE_SITE_URL . "/wp-sitemap.xml\n";
}, PHP_INT_MAX, 2 );
